import { installServerChildCrashObserver } from "./server-child-crash.mjs";

// FIRST STATEMENT IN THE FILE, AND IT SHOULD STAY FIRST. This process holds
// every bot, the memory, the tools, the browser and the phone, and twice on
// 2026-09-22 it died without leaving a word about why. The observer below does
// not stop it dying — `uncaughtExceptionMonitor` cannot, by construction, and
// swallowing an unknown fault would keep a corrupted server answering health
// checks. It writes one redacted line synchronously on the way out. See
// server-child-crash.mjs.
//
// The honest limit of "first": ES modules evaluate every import before this
// line runs, so a fault thrown while one of the modules above is still
// initialising happens before there is an observer to see it. Everything from
// the lease acquisition and store construction below — which is where boot
// actually does work that can fail — is covered.
installServerChildCrashObserver();
// The transcript backfill starts when the database opens, and the first open comes before listen (the top-level awaits below hand the loop back,
// so a chunk could write in the listen window). Its writes are held to the first health answer from here, before anything opens the file.
holdTranscriptBackfillUntil(startupWritesReady());

// Node has already read NODE_COMPILE_CACHE for this process. Engine CLIs, MCP
// servers and bot commands start from this environment, and must not write
// their own compiled code into the app's cache folder.
delete process.env.NODE_COMPILE_CACHE;

// Kept below installServerChildCrashObserver(): nothing executable may precede it (server-child-crash.test.ts).
const USER_CHROME_ALLOW_PANEL_MESSAGE = "Chrome did not let Murage connect. When Chrome asks \"Allow remote debugging?\", click Allow, then try again.";

const PORT = Number(process.env.MURAGE_PORT || process.env.MURAGEBOX_PORT || 8799);
const WEBHOOK_PORT = Number(process.env.MURAGE_WEBHOOK_PORT || PORT + 1);
const STATIC_DIR = process.env.MURAGE_STATIC_DIR || null;
/** A Cloud home tells its own app which home it is (the "Continue from murage.ai" link): MURAGE_CLOUD_MACHINE_ID (equals cloud_homes.id), else the pinned control-plane binding. Never taken from the URL. */
let cloudHomeIdSource: (() => string | undefined) | undefined;
function withCloudHomeId(html: Buffer): Buffer {
  let id: string | undefined;
  try { id = process.env.MURAGE_CLOUD_MACHINE_ID || cloudHomeIdSource?.(); } catch { id = undefined; }
  if (!id || !/^[A-Za-z0-9_-]{1,128}$/.test(id)) return html;
  let site = "";
  try { const u = new URL(process.env.MURAGE_SITE_ORIGIN ?? ""); if (u.protocol === "https:" && u.pathname === "/" && !u.search && !u.hash && !u.username && !u.password) site = `<meta name="murage-site-origin" content="${u.origin}">`; } catch { /* no site origin: the page shows the add-device steps only */ }
  // The light opening screen paints the first frame (server/cloud-home/opening-screen.ts): the home's policy blocks index.html's inline palette script.
  return Buffer.from(withCloudOpening(html.toString("utf8")).replace("<head>", `<head><meta name="murage-home-id" content="${id}">${site}`));
}
const MIME: Record<string, string> = {
  ".html": "text/html",
  ".js": "text/javascript",
  // the call's speech detector: ONNX Runtime Web loads its glue as a module
  // (a module served as anything but JavaScript is refused) and compiles
  // its WebAssembly by streaming, which requires this exact type
  ".mjs": "text/javascript",
  ".wasm": "application/wasm",
  ".css": "text/css",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".webp": "image/webp",
  ".ico": "image/x-icon",
  ".json": "application/json",
  ".woff2": "font/woff2",
  // A manifest served as anything but this is ignored, silently, and the
  // browser simply never offers to install. It falls through to
  // application/octet-stream without this line. The browser door carries its
  // own copy of this table (companion/src/browser.ts) and got there first;
  // `src/lib/pwa-install.test.ts` now pins the two together, because the
  // desktop reads this one and a phone reads that one.
  ".webmanifest": "application/manifest+json",
};

// Acquire before migration, provider discovery or Store construction. An
// Electron child consumes its parent's private capability here; it must not
// survive in the environment inherited by any provider or MCP process.
const dataDirLease = acquireDataDirLeaseForProcess(DATA_DIR);
recoverPackageImportTransaction(DATA_DIR, { assertOwned: () => {
  if (!dataDirLease) throw new Error("Installation ownership is required");
} });
assertRestoreReviewed(DATA_DIR);
let dataWritersStopped = false;
let slack: SlackService | undefined;
let slackBinding: SlackBinding | undefined;
let slackOperationBusy = false;
let slackRequiresRevoke = false;
let discord: DiscordService | undefined;
let discordBinding: DiscordBinding | undefined;
let discordOperationBusy = false;
let discordRequiresRevoke = false;
let whatsapp: WhatsAppService | undefined;
let whatsappBinding: WhatsAppBinding | undefined;
let whatsappOperationBusy = false;
process.once("exit", () => {
  // A forced/crashed shutdown leaves a stale record for conservative recovery
  // after the OS confirms this PID is dead. Do not claim cleanup completed.
  if (!dataWritersStopped) return;
  try { dataDirLease.release(); }
  catch { /* Retain the lease on uncertain ownership; never remove another's. */ }
});
ensureDirs();
assertRestoreReviewed(DATA_DIR);
// User-added local model servers live under the data dir (LM1); until this
// runs the store is inert, so no engine writer can see a user address.
configureLocalServerStore(DATA_DIR);
const cfg = loadConfig();
// Lines the server writes into an outside chat read in the owner's app language, read live (channels/reply-text.ts).
setChannelReplyLanguage(() => cfg.language);
// Rule 57a (APP-GRANT-DESIGN-FINAL.AGREED-r10.md), once at load before any
// ask is judged: of any stored servers whose names an engine cannot tell
// apart, the first keeps its name and each later one is turned off with the
// reason shown in Settings. Nothing is renamed.
/** Rule 72: the one three-strike counter for narrowing denials. */
const narrowDenials = new NarrowDenials();
// Rule 74a: the last validated owner environment is kept under the data dir.
