// ── computer control (who is driving) ──────────────────────────────────
// The person can take the wheel of a bot's computer from the panel; while
// they hold it, the bot's computer proxies refuse every action. The record
// lives here; the proxies consult it over loopback with the boot token.
const computerControlRevision = new Map<string, number>();
let hostControlRevision = 0;
const computerControl = new ComputerControl((botId, snapshot) => {
  hostControlRevision++;
  computerControlRevision.set(botId, (computerControlRevision.get(botId) ?? 0) + 1);
  // One-way, fail-closed mirror into the Electron process that owns the
  // native browser. Never send release: a loopback caller can influence the
  // server record, while only the trusted Browser panel may clear Electron's
  // local gate after its server-first release succeeds.
  if (snapshot.held && /^[A-Za-z0-9_-]{1,120}$/.test(botId)) {
    postDesktopPrivateMessage({ type: "murage:browser-control", botId, held: true });
  }
  broadcast({ kind: "computer-control", botId, held: snapshot.held, helpReason: snapshot.helpReason });
});
const controlLeaseIdSchema = z.string().min(16).max(120).regex(/^[A-Za-z0-9_-]+$/);
const routineRequestSourceSchema = {
  fromBotId: z.string().min(1).max(128),
  fromThreadId: z.string().min(1).max(128),
};
const routineRequestEnvelopeSchema = z.discriminatedUnion("action", [
  z.object({ ...routineRequestSourceSchema, action: z.literal("create"), routine: z.unknown(), forBotId: z.unknown().optional() }).strict(),
  z.object({
    ...routineRequestSourceSchema,
    action: z.literal("update"),
    routineId: z.unknown(),
    changes: z.unknown(),
  }).strict(),
  ...(["pause", "resume", "run_now", "delete"] as const).map((action) =>
    z.object({ ...routineRequestSourceSchema, action: z.literal(action), routineId: z.unknown() }).strict()
  ),
]);
/** A webhook proposed from chat (SL-J J1): no rotate and no run now. */
const webhookRequestEnvelopeSchema = z.discriminatedUnion("action", [
  z.object({ ...routineRequestSourceSchema, kind: z.literal("webhook"), action: z.literal("create"), webhook: z.unknown() }).strict(),
  z.object({ ...routineRequestSourceSchema, kind: z.literal("webhook"), action: z.literal("update"), webhookId: z.unknown(), changes: z.unknown() }).strict(),
  ...(["pause", "resume", "delete"] as const).map((action) =>
    z.object({ ...routineRequestSourceSchema, kind: z.literal("webhook"), action: z.literal(action), webhookId: z.unknown() }).strict()
  ),
]);
/** One plain line for every proposal the route refuses (SL-J J1). */
const UNDO_ONLY_AUTOMATIONS = "Undo works only on a routine or webhook change that was applied.";
const AUTOMATION_PROPOSAL_REFUSED = "Routines and webhooks can only be set up in the owner's own conversation with this bot, not from a routine or webhook run, a channel message, a room or a conversation for someone else.";

/** The loopback endpoint a bot's computer proxy polls before acting. */
// Cloud home: a turn's hosted computer is reached only through the box relay
// (box-relay.ts). The bot's bound box is recorded here when a turn mounts it.
const boxBindings = new Map<string, string>();
const boxRelayDeps: BoxRelayDeps = {
  resolveClaim: (header) => internalCapabilities.resolve(header),
  isActive: (claim) => internalCapabilities.isActive(claim),
  boundBoxId: (botId) => boxBindings.get(botId),
  accountToken: () => cfg.box?.token,
  enabled: () => isCloudHome() && cloudBoxComputersAllowed(cfg),
  upstreamBase: box.BOX_API_BASE,
  log: (line) => console.warn(line),
};

function controlIntegration(botId: string, threadId: string, generation: string) {
  return {
    url: `http://127.0.0.1:${PORT}/api/internal/computer-control?botId=${encodeURIComponent(botId)}`,
    token: internalToken(botId, threadId, generation, "computer"),
  };
}

function hostComputerIntegration(botId: string, threadId: string, generation: string, connection: LocalComputerConnection, adapter?: Pick<ProviderAdapter, "askHostAction">): LocalComputerConnection {
  const control = controlIntegration(botId, threadId, generation);
  hostComputerThreads.set(threadId, { botId, ownerId: generation, connection, ...(adapter ? { adapter } : {}) });
  return { ...connection, command: process.execPath, args: [SPAWNED_PROXIES.hostComputer], env: {
    ...AGENTS_NODE_FLAG, MURAGE_BOT_ID: botId, MURAGE_THREAD_ID: threadId,
    MURAGE_CONTROL_URL: control.url, MURAGE_CONTROL_TOKEN: control.token,
  } };
}

/** Run a turn on `targetBotId` and resolve with its assistant text — the
 * synchronous half of ask_bot. Subscribes to the bus, folds assistant_text
 * for that thread, resolves on turn.completed (or the short inline wait budget). */

/** An ask's outcome: the target's words stay sealed as worker text, and a failure's detail is reduced to a code before it leaves this function. */
function askOutcome(status: AskBotOutcome["status"], text: string, extra: { stopCode?: FailureCode; startCode?: StartWhy; copyOf?: Message["copyOf"]; ticket?: string } = {}): AskBotOutcome {
  return { status, text: new WorkerText(text), hasText: text.trim() !== "", ...extra };
}

function askBotAndWait(targetBotId: string, message: string, depth: number, _fromBotId?: string, eventId?: string, coordination?: CoordinationTrace, sourceThreadId?:string, notOwnerAudience = false, handoffOf?: { threadId: string; messageId: string }, onTimeout?: AskTicketFactory): Promise<AskBotOutcome> {
  const target = store.bot(targetBotId);
  if (!target) return Promise.resolve(askOutcome("error", "", { startCode: "not_reachable" }));
  const task=audienceTask(store,targetBotId,threadHumanPrincipal(sourceThreadId??defaultThreadId(target)), sourceThreadId ? sourceExecutionAudience(_fromBotId, sourceThreadId) : null);
  if(!task)return Promise.resolve(askOutcome("error", "", { startCode: "not_reachable" }));
  const threadId = task.threadId;
  const releaseSlot = holdCoordinationSlot(threadId);
  return new Promise((resolve) => {
    let text = "";
    let turnId: string | undefined;
    const since = Date.now();
    let done = false;
    let settling = false;
    let cancelSettle: () => void = () => undefined;
    const finish = (out: AskBotOutcome) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      cancelSettle();
      unsub();
      resolve(out);
    };
    const unsub = bus.subscribe((e: RuntimeEvent) => {
      // A cancelled provider may flush text/completion after its replacement
      // has started on the same thread. Retired turn ids must never satisfy a
      // newer ask_bot waiter with the old partial reply.
      if (shouldIgnoreProviderEvent(e)) return;
      if (e.threadId !== threadId) return;
      if (e.turnId) turnId = e.turnId;
      if (e.type === "item.completed" && e.itemType === "assistant_text" && !isMemoryProvenanceEcho(e.text)) {
        text += (text ? "\n" : "") + e.text;
      } else if (e.type === "turn.completed") {
        // every outcome that carries text carries its link: a failed turn's
        // partial reply is mirrored too
        // The reply's own row can be stored a moment after this event: the answer waits for it (on this bus, within the grace) and is
        // never released before it. A row that never comes leaves no link, and the result gate withholds the text.
        if (settling) return;
        settling = true;
        cancelSettle = settleWithOrigin({
          lookup: () => turnReplyCopy(threadId, turnId, since),
          needed: text.trim().length > 0,
          // the stored reply row wakes the wait itself, as well as any later runtime event: an origin that arrives early settles the ask at once
          onSignal: (listener) => {
            const offBus = bus.subscribe((later: RuntimeEvent) => { if (later.threadId === threadId) listener(); });
            const offStore = store.onChange(change => { if (change.type === "message" && change.threadId === threadId) listener(); });
            return () => { offBus(); offStore(); };
          },
          graceMs: ASK_ORIGIN_GRACE_MS,
        }, (copyOf) => {
          if (turnSucceeded(e)) finish(askOutcome("reply", text, { copyOf }));
          else if (turnStopped(e)) finish(askOutcome("stopped", text, { stopCode: failureCodeFrom(e.stopReason), copyOf }));
          else finish(askOutcome("failed", text, { stopCode: failureCodeFrom(e.stopReason), copyOf }));
        });
      }
    });
    // Timing out does NOT stop the peer's turn. The still-running work becomes a delegation claim ticket HERE, in this tick, against the turn's real state
    // (F3 02-4): a turn that completed is settling its reply, which is returned (no ticket); a running one gets its ticket row and watch written first, then
    // the timeout carries the ticket. A ticket that could not be written is no ticket: the ask ends as an error.
    const timer = setTimeout(() => {
      const verdict = askTimeoutVerdict({ done, settling }, onTimeout ? () => onTimeout({ threadId, ...(turnId ? { turnId } : {}) }) : undefined);
      if (verdict.kind === "settling") return;
      if (verdict.kind === "error") { finish(askOutcome("error", "", { startCode: "setup" })); return; }
      // the peer's turn not seen yet: once it is, the ticket records it, so a restart reports it interrupted rather than holding it for the owner
      if (verdict.ticket && !turnId) {
        const ticketId = verdict.ticket;
        const offAccept = bus.subscribe((later: RuntimeEvent) => {
          if (shouldIgnoreProviderEvent(later) || later.threadId !== threadId) return;
          if (later.turnId) {
            try { markAskTicketAccepted(ticketId, later.turnId); } catch (error) { console.error(`[ask] the peer took the turn of ticket ${ticketId} but the record could not be written; a restart will hold it for the owner`, error); }
            offAccept();
          } else if (later.type === "turn.completed") offAccept();
        });
      }
      finish(askOutcome("timeout", text, { copyOf: turnReplyCopy(threadId, turnId, since), ...(verdict.ticket ? { ticket: verdict.ticket } : {}) }));
    }, ASK_BOT_TIMEOUT_MS);
    startTurn(targetBotId, message, {
      threadId,
      commsDepth: depth + 1,
      automation:{kind:"ask"},
      chainRootThreadId: sourceThreadId,
      ...(sourceThreadId ? { handoffSourceThreadId: sourceThreadId } : {}),
      ...(sourceThreadId && handoffOf?.threadId === sourceThreadId ? { handoffOf } : {}),
      eventId,
      coordination,
      ...peerRoutineTurnOptions(target, sourceThreadId, _fromBotId),
      ...(notOwnerAudience ? { notOwnerAudience: true } : {}),
      onDispatchError: (reason, error) => { releaseSlot(); finish(askOutcome("error", "", { startCode: startFailureCodeFrom(error ?? reason) })); },
    }).catch((err) => {
      const reason = err instanceof Error ? err.message : String(err);
      // Refused before the turn began (an unsupported setting, a closed gate): nothing of its own was written in the asked bot's conversation.
      // The owner reads the full explanation there; the asking bot is told only the kind of failure.
      recordRefusedStart(store, threadId, reason);
      releaseSlot(); finish(askOutcome("error", "", { startCode: startFailureCodeFrom(err) }));
    });
  });
}

// default selection for new bots: first available instance, Fuigo preferred
async function defaultSelection(): Promise<EngineChoice> {
  return pickDefaultEngine(await describedInstances({ catalogs: "due" }));
}

/** What a bot gains or loses moving from one engine to another (triage row
 * 22), for update_bot and create_bot results. Empty on the same engine. */
function engineSwitchNotes(fromInstanceId: string, toInstanceId: string): string[] {
  if (fromInstanceId === toInstanceId) return [];
  return engineSwitchLines(registry.get(fromInstanceId)?.adapter.capabilities, registry.get(toInstanceId)?.adapter.capabilities, registry.get(toInstanceId)?.displayName);
}

const hermesImportRequestSchema = z.object({ profiles: z.array(z.string().min(1).max(80)).min(1).max(MAX_WORKSPACE_BOTS) }).strict();
/** Each Hermes profile some bot already runs, with that bot's name. */
function hermesProfileBots(): Map<string, string> {
  const profiles = hermesInstanceProfiles(instanceConfigs(cfg), process.env);
  const out = new Map<string, string>();
  for (const bot of store.bots) {
    const profile = profiles.get(bot.modelSelection.instanceId);
    if (profile !== undefined && !out.has(profile)) out.set(profile, bot.name);
  }
  return out;
}

function checkedModelSelection(
  raw: unknown,
  current?: { selection: ModelSelection; busy: boolean },
  requireAvailableModel = false,
): { ok: true; selection: ModelSelection } | { ok: false; status: number; error: string } {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return { ok: false, status: 400, error: "modelSelection must be an object" };
  }
  const value = raw as { instanceId?: unknown; model?: unknown; effort?: unknown; connectionId?: unknown };
  if (typeof value.instanceId !== "string" || !value.instanceId.trim()) {
    return { ok: false, status: 400, error: "modelSelection.instanceId is required" };
  }
  if (typeof value.model !== "string" || !value.model.trim()) {
    return { ok: false, status: 400, error: "modelSelection.model is required" };
  }
  const selection: ModelSelection = {
    instanceId: value.instanceId.trim(),
    model: value.model.trim(),
  };
  if (value.connectionId !== undefined) {
    if (typeof value.connectionId !== "string" || !/^[A-Za-z0-9_-]{1,120}$/.test(value.connectionId)) return { ok: false, status: 400, error: "modelSelection.connectionId is invalid" };
    selection.connectionId = value.connectionId;
  }
  if (value.effort !== undefined) {
    if (!isEffortLevel(value.effort)) {
      return { ok: false, status: 400, error: `effort "${String(value.effort)}" is not recognized` };
    }
    selection.effort = value.effort;
  }
  const changed = current && (
    selection.instanceId !== current.selection.instanceId ||
    selection.model !== current.selection.model ||
    selection.effort !== current.selection.effort || selection.connectionId !== current.selection.connectionId
  );
  if (current?.busy && changed) {
    return { ok: false, status: 409, error: "the bot is working: stop it before changing models" };
  }
  const hidden = cloudEngineChoiceRefusal(cloudHome, allInstanceConfigs(cfg)[selection.instanceId]?.driver, !current || Boolean(changed));
  if (hidden) return { ok: false, status: 403, error: hidden };
  const target = registry.get(selection.instanceId);
  // Model IDs remain free-form at the app's general API boundary. Custom
  // engines can accept IDs that are not in their discovery catalog, and
  // several drivers only learn the final catalog when a turn starts. The
  // MCP tool applies a stricter discovered-model policy for its own calls.
  if (selection.connectionId) {
    try { if (!target) throw new Error("Selected engine is unavailable"); modelSignIns.revokeGatewayKey(selectedProviderRoute(selection, target.driverKind, { admission: false })?.apiKey); }
    catch (error) { return { ok: false, status: 409, error: (error as Error).message }; }
  }
  if (requireAvailableModel && !selection.connectionId) {
    if (!target) {
      return { ok: false, status: 400, error: `model instance "${selection.instanceId}" is unavailable` };
    }
    const offered =
      selection.model === target.models.default ||
      target.models.options.some((option) => option.id === selection.model);
    if (!offered) {
      return {
        ok: false,
        status: 400,
        error: `model "${selection.model}" is not offered by instance "${selection.instanceId}"`,
      };
    }
  }
  const allowed: readonly string[] = target?.adapter.capabilities.effortLevels ?? [];
  if (target && selection.effort !== undefined && !allowed.includes(selection.effort)) {
    return { ok: false, status: 400, error: `effort "${selection.effort}" is not offered by this bot's engine` };
  }
  return { ok: true, selection };
}

function checkedGroupResponder(value: unknown, memberIds: string[]): GroupDefaultResponder | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const responder = value as { kind?: unknown; botId?: unknown };
  if (responder.kind === "everyone") return { kind: "everyone" };
  if (responder.kind === "mentions") return { kind: "mentions" };
  if (responder.kind === "auto") {
    const fallback = (responder as { fallbackBotId?: unknown }).fallbackBotId;
    return typeof fallback === "string" && memberIds.includes(fallback) ? { kind: "auto", fallbackBotId: fallback } : { kind: "auto" };
  }
  if (
    responder.kind === "member" &&
    typeof responder.botId === "string" &&
    memberIds.includes(responder.botId)
  ) {
    return { kind: "member", botId: responder.botId };
  }
  return null;
}

function checkedMemberIds(value: unknown): { ok: true; memberIds: string[] } | { ok: false; error: string } {
  if (!Array.isArray(value)) return { ok: false, error: "memberIds must be a list of bot IDs" };
  const invalidIndex = value.findIndex(
    (id) => typeof id !== "string" || !id.trim() || !store.bot(id),
  );
  if (invalidIndex !== -1) {
    return { ok: false, error: `unknown channel member: ${String(value[invalidIndex])}` };
  }
  const memberIds = [...new Set(value as string[])];
  if (!memberIds.length) return { ok: false, error: "a channel needs at least one bot" };
  // A room whose every member is archived accepts messages and answers none of
  // them — the failure only surfaces later, as "… is archived and can't
  // respond" on the first turn. Refuse it here, where the mistake is made.
  if (memberIds.every((id) => store.bot(id)?.hidden)) {
    return {
      ok: false,
      error: "a channel needs at least one active bot: every member given is archived",
    };
  }
  return { ok: true, memberIds };
}
let bootSelection = { instanceId: "", model: "" };
// Every new bot gets the workspace's new-bot effort where its engine offers
// that level (triage row 23); an explicit effort wins.
const store = new Store(() => bootSelection, (selection) => withNewBotEffort(selection, cfg.newBots?.effort, registry.get(selection.instanceId)?.adapter.capabilities.effortLevels), true);
// A bot that still exists keeps its engine state roots: its tasks hold cursors into them (scoped-cli-home.ts retireScopes).
setScopeRetentionHooks({ botExists: (botId) => Boolean(store.bot(botId)) });
// Codex hook env files (0600) left by a closed Murage or a bot never launched again: swept for every bot scope at app start (codex-hook.ts).
sweepAllHookEnv(scopedCliHomeRoot("codex"));
setLoginSplitHook(({ kind, botId }) => { warmPool.drainScope({ kind, bot: botId }); });
// Cloud home: a tombstoned bot id is never minted again, and a bot is deleted only after the launcher
// released its state (server/cloud-home/bot-state.ts). No-op on a desktop.
installCloudBotGuards(store);
// What asker wakes the last run owed (asker-wake.ts): restored before anything can deliver a result; the sweeps and turn ends wake them.
