bus.subscribe((event: RuntimeEvent) => {
  if (shouldIgnoreProviderEvent(event)) return;
  if (event.type !== "turn.completed") return;
  // A turn that failed or was interrupted drops its queue rather than
  // firing it later: the user who hit Stop does not expect the delegations
  // that turn queued to run anyway, minutes later, on an unrelated turn.
  // Scoped to the interrupted bot where the thread names one. A room queue
  // holds handoffs from every bot that has spoken there, and one member
  // being interrupted must not cancel another member's. A room thread names
  // no owner, so the discard falls back to thread-wide there — bounded by
  // the rule in discardDelegations that an item which has already outlived a
  // turn is never collateral.
  // (a wake turn that ended badly restarts nothing; the done ids stay for the one rebuild a late memory refusal schedules, asker-wake.ts failed)
  if (settleQueuedDelegations(commsBus, approvalBus, event.threadId, event, store.botByThread(event.threadId)?.id) === "discarded") askerWakes.failed(event.threadId);
  // Every owed wake is tried, not only this thread's: a wake held back while
  // its bot was busy in a room or on three threads is freed by a turn that
  // ended somewhere else. wakeAsker starts nothing for a thread still busy.
  queueMicrotask(() => { for (const threadId of askerWakes.threads()) wakeAsker(threadId); });
  // A settling bot frees itself as a delegation TARGET too: handoffs that
  // found it busy earlier were kept queued (bounded retries) on their own
  // source threads, and this is the moment they get their retry.
  const settledBot = store.botByThread(event.threadId);
  if (settledBot) retryDelegationsWaitingOn(settledBot.id);
});

// ── steer-queue drain: messages sent while the bot was busy ────────────
// Runs on ANY turn.completed rather than resolving the settling thread: a
// bot busy in a room settles on the room's thread, and by the time this
// subscriber runs the main fold has already dropped the speaker record —
// so the drain matches on "this queue's bot is idle now" instead.
// Registration order puts this after the main fold, so busy is already
// false when it looks. Deliberately NOT gated on event.ok (unlike the
// delegation drain above): queued delegations are a bot's fan-out and
// dropping them on Stop is a safety property, but queued messages are the
// user's own words — stop-then-steer is the point, so an interrupted turn
// drains too.
bus.subscribe((event: RuntimeEvent) => {
  if (shouldIgnoreProviderEvent(event)) return;
  if (event.type !== "turn.completed") return;
  drainQueuedSends();
});

// ── engine "/" commands (server/engine-commands.ts) ─────────────────────
// A driver reports its engine's command list on `engine.commands`; it is
// filed under the bot that ran the turn (a direct task, or the member
// speaking in a room) so the composer's menu is full on the next visit
// without waiting for the engine to start again.
const engineCommandCache = new EngineCommandCache();
bus.subscribe((event: RuntimeEvent) => {
  if (event.type !== "engine.commands" || shouldIgnoreProviderEvent(event)) return;
  const botId = store.botByThread(event.threadId)?.id ?? groupSpeakers.get(event.threadId)?.botId;
  if (botId) engineCommandCache.record(botId, event.provider, event.commands);
});

// A steer the driver reported uncertain carries "Sent to the bot; it hasn't
// confirmed yet." until the engine's late echo (`steer.confirmed`) clears
// it by the id the steer was sent under.
bus.subscribe((event: RuntimeEvent) => {
  if (event.type !== "steer.confirmed" || shouldIgnoreProviderEvent(event)) return;
  // Exactly the named message, on its own thread. Never the oldest one.
  const pending = steerToConfirm(store.keyedCards(event.threadId, "steer", typeof event.interjectionId === "string" ? event.interjectionId : "\u0000"), event.interjectionId);
  // confirmed: the row now names the turn the words went into (turn-attribution.ts)
  const turnId = pending && typeof event.interjectionId === "string" ? turnAttribution.confirmed(takeUncertainSteer(event.interjectionId), pending.id) : undefined;
  if (pending) store.patchMessage(event.threadId, pending.id, { steerUnconfirmed: false, ...(turnId ? { dispatchedIn: turnId } : {}) });
});

/** The owner's typed "/name args" when `name` is one of this bot's engine
 * commands on `driver`; null for everything else, which stays chat. */
function engineCommandForTurn(botId: string, driver: string, text: string) {
  if (!engineReportsCommands(driver)) return null;
  return engineCommandInText(text, engineCommandsView(engineCommandCache, botId, driver).commands);
}

/** How a room member turn that never started gives the room and the bot
 * back (server/room-turn-release.ts): the same steps everywhere, bound to
 * the store, the speaker records, the browser capabilities and the queues. */
const unstartedRoomTurnReleaseDeps = {
  roomBusyBotId: (groupId: string) => store.group(groupId)?.busyBotId,
  botBusy: (botId: string) => store.bot(botId)?.busy === true,
  clearRoomClaim: (groupId: string, threadId: string) => {
    groupSpeakers.delete(threadId);
    store.patchGroup(groupId, { busyBotId: null, unread: true });
  },
  idleBot: (botId: string) => {
    store.setActivity(botId, "idle");
    retryDelegationsWaitingOn(botId);
  },
  releaseBrowser: (threadId: string, ownerId: string) => releaseBrowserCapabilityForThread(threadId, ownerId),
  // No turn.completed follows a room turn that never started. Anything
  // queued while this bot briefly owned the room must be retried now.
  drainQueues: () => {
    drainQueuedSends();
    drainConnectorResumes();
    drainSecretResumes(); void browserSetup?.drain(); void browserExtension?.approvals.drain().catch(() => {});
    drainTeamIncidents();
  },
};

